<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Students Report Card</h1><p>Uses the persisted exam and grading engine.</p></div><button class="btn btn--primary" type="button" onclick="window.print()">Print</button></header><form class="filter-bar filter-bar--compact"><div class="module-field"><label>Exam</label><select class="module-select" name="exam" required><option value="">Select Exam</option><?php foreach($exams as$e):?><option value="<?= $e['id'] ?>" <?= $selectedExam==$e['id']?'selected':'' ?>><?= e($e['name']) ?></option><?php endforeach ?></select></div><div class="module-field"><label>Student</label><select class="module-select" name="student" required><option value="">Select Student</option><?php foreach($students as$s):?><option value="<?= $s['id'] ?>" <?= $selectedStudent==$s['id']?'selected':'' ?>><?= e($s['registration_no'].' — '.$s['student_name']) ?></option><?php endforeach ?></select></div><button class="btn btn--primary">View Result</button></form><?php if($result):?><section class="module-card"><div class="module-card__body"><div class="table-scroll"><table class="data-table"><thead><tr><th>Subject</th><th>Total</th><th>Obtained</th></tr></thead><tbody><?php foreach($result['subjects']as$row):?><tr><td><?= e($row['subject']) ?></td><td><?= e($row['total_marks']) ?></td><td><?= e($row['obtained_marks']) ?></td></tr><?php endforeach ?></tbody></table></div><h3>Total: <?= e($result['obtained']) ?> / <?= e($result['total']) ?> · <?= number_format($result['percentage'],2) ?>% · Grade <?= e($result['grade']['grade']??'—') ?> (<?= e($result['grade']['status']??'Not configured') ?>)</h3></div></section><?php endif ?></div></div></main>
